fn log(name: &str) -> String {
    let p = std::env::temp_dir().join(format!("spine-tests-4766-{}-{name}.log", std::process::id()));
    let mut f = std::fs::File::create(&p).unwrap();
    for (ts, id) in [("2026-11-16T20:00:01", "a"), ("2026-11-16T20:00:02", "b"), ("2026-11-16T20:00:03", "c")] {
        writeln!(f, r#"{{"timestamp":"{ts}","event":"agent.action","role":"wren","phase":"started","call_id":"{id}","tool":"Bash","session_id":"s"}}"#).unwrap();
    }
    p.to_string_lossy().into_owned()
}

/// NEGATIVE PROOF for the filter: `.lt` keeps only the earlier rows. If lt and gt were
/// swapped, `.lt=…02` would return c, not a.
#[test]
fn a_less_than_filter_keeps_the_earlier_rows() {
    let Some(class) = spine_class() else { return };
    let Some(ts) = class.fields.iter().find(|f| f.name.to_ascii_lowercase().ends_with("ts")) else { return };
    let rows = SpineRows { path: log("lt"), max: 1 << 20 };
    let mut w = Where::default();
    w.bounds.push((ts.name.to_string(), "<", "2026-11-16T20:00:02".into()));
    let (got, _) = rows.list_where(class, 10, 0, None, &w).unwrap();
    assert_eq!(got.iter().map(|r| r["name"].as_str().unwrap().to_string()).collect::<Vec<_>>(), ["a"]);
    let mut w = Where::default();
    w.bounds.push((ts.name.to_string(), ">", "2026-11-16T20:00:02".into()));
    let (got, _) = rows.list_where(class, 10, 0, None, &w).unwrap();
    assert_eq!(got.iter().map(|r| r["name"].as_str().unwrap().to_string()).collect::<Vec<_>>(), ["c"]);
}

